                add_right = d(right, c) + d(c, depot) - d(right, depot)
                cand = (min(add_left, add_right), add_left, add_right, c)
                if best is None or cand < best:
                    best = cand
            if best is None:
                break
            _, add_left, add_right, c = best
            if add_left <= add_right:
                r.insert(0, c)
            else:
                r.append(c)
            load += demand[c]
            remaining.remove(c)

        routes.append(r)

    used = set()
    cleaned = []
    for r in routes:
        nr = []
        for c in r:
            if c in customers and c not in used:
                nr.append(c)
                used.add(c)
        if nr:
            cleaned.append(nr)
    routes = cleaned

    for c in sorted(customers):
        if c not in used:
            routes.append([c])
            used.add(c)

    improved = True
    while improved:
        improved = False

        for i in range(len(routes)):
            r = routes[i]
            if len(r) < 3:
                continue
            base = route_cost(r)
            best_gain = 0
            best_r = None
            n = len(r)
            for a in range(n - 1):
                for b in range(a + 1, n):
                    nr = r[:a] + r[a:b + 1][::-1] + r[b + 1:]
                    gain = base - route_cost(nr)
                    if gain > best_gain or (gain == best_gain and best_r is not None and nr < best_r):
                        best_gain = gain
                        best_r = nr
            if best_r is not None and best_gain > 1e-12:
                routes[i] = best_r
                improved = True

        if improved:
            continue

        for i in range(len(routes)):
            for j in range(len(routes)):
                if i == j or not routes[i]:
                    continue
                ri = routes[i]
                rj = routes[j]
                li = route_load(ri)
                lj = route_load(rj)
                best_move = None
                for idx, c in enumerate(ri):
                    dem = demand[c]
                    if lj + dem > capacity:
                        continue
                    nri = ri[:idx] + ri[idx + 1:]
                    if not nri:
                        continue
                    base = route_cost(ri) + route_cost(rj)
                    for pos in (0, len(rj)):
                        nrj = rj[:]
                        nrj.insert(pos, c)
                        gain = base - (route_cost(nri) + route_cost(nrj))
                        cand = (gain, idx, pos, nri, nrj)
                        if best_move is None or cand > best_move:
                            best_move = cand
                if best_move is not None and best_move[0] > 1e-12:
                    _, _, _, nri, nrj = best_move
                    routes[i] = nri
                    routes[j] = nrj
                    improved = True
                    break
            if improved:
                break

        routes = [r for r in routes if r]

    seen = set()
    final_routes = []
    for r in routes:
        nr = []
        for c in r:
            if c in customers and c not in seen:
                nr.append(c)
                seen.add(c)
        if nr:
            final_routes.append(nr)

    for c in sorted(customers):
        if c not in seen:
            final_routes.append([c])
            seen.add(c)

    final_routes.sort(key=lambda r: (route_load(r), len(r), r[0] if r else -1))
    return final_routes
